import type { AppState, TeachingSection } from "@/domain/types";

const section = (levelId: string, streamId: string, index: number, topicId: string): TeachingSection => ({ id: `${levelId}-${streamId}-biology`, teacherId: "fixture-teacher", subjectName: "Biology", levelId, streamId, termId: "fixture-term", topicId, scheduledEntryIds: [`entry-${index}`], confirmedOutcomeIds: [], currentOutcomeStatus: "UNCONFIRMED", unfinishedWorkIds: [], constraints: streamId === "east" ? ["Four microscopes available"] : [] });
const sections = [section("s1", "east", 1, "bio-s1-t1-1.1"), section("s1", "west", 2, "bio-s1-t1-1.1"), section("s1", "north", 3, "bio-s1-t1-1.1"), section("s2", "east", 4, "bio-s2-t2-3.2"), section("s2", "west", 5, "bio-s2-t2-3.2"), section("s2", "north", 6, "bio-s2-t2-3.2")];
const timetable = sections.map((s, i) => ({ id: `entry-${i + 1}`, day: i % 2 === 0 ? "Monday" : "Tuesday", period: (i % 4) + 1, startsAt: `${8 + (i % 4)}:00`, endsAt: `${9 + (i % 4)}:00`, sectionId: s.id, room: `Room ${i % 2 + 1}`, verificationStatus: "CONFIRMED" as const, confidence: 1 }));
const lessons = sections.map((s, i) => ({ id: `lesson-${i + 1}`, sectionId: s.id, timetableEntryId: timetable[i].id, date: "2026-09-08", status: i === 0 ? "DUE" as const : "SCHEDULED" as const, topicId: s.topicId, segmentIds: ["segment-context", "segment-activity", "segment-check"] }));
export const fixtureState: AppState = { school: { id: "fixture-school", name: "Fixture School", location: "Test location" }, term: { id: "fixture-term", name: "Fixture period", academicYear: 2026 }, people: [{ id: "fixture-teacher", displayName: "Fixture Teacher", roles: ["TEACHER"], departmentIds: ["biology"] }], levels: [{ id: "s1", name: "Senior 1" }, { id: "s2", name: "Senior 2" }], streams: [{ id: "east", name: "East" }, { id: "west", name: "West" }, { id: "north", name: "North" }], timetable, sections, lessons, outcomes: [], unfinished: [], recovery: [], exceptions: [], resources: [], assessments: [] };
